.ai-summary-container {
    max-width: 500px;
    margin: 30px auto;
    font-family: Arial,sans-serif
}

.ai-summary-box {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    width: 590px;
    height: 363px;
    padding: 1pc 2pc 2pc;
    -webkit-box-orient: vertical;
    -webkit-box-direction: normal;
    -ms-flex-direction: column;
    flex-direction: column;
    -webkit-box-align: end;
    -ms-flex-align: end;
    align-items: flex-end;
    gap: 1pc;
    border: 1px solid #ccc;
    margin-top: 20px;
    background: #f9f9f9
}

#aiGenerateBtn,#aiValidateBtn {
    display: -webkit-inline-box;
    display: -ms-inline-flexbox;
    display: inline-flex;
    padding: 9pt 1pc;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    justify-content: center;
    -webkit-box-align: center;
    -ms-flex-align: center;
    align-items: center;
    gap: 1pc;
    border-radius: 75pt;
    background: #3c84c9;
    color: #fff;
    border: none;
    font-weight: 500;
    font-size: 1pc;
    margin-top: 10px;
    cursor: pointer;
    -webkit-transition: all .3s ease;
    transition: all .3s ease;
    white-space: nowrap;
    width: 100%;
    height: 100%
}

#aiGenerateBtn:not(:disabled):hover,#aiValidateBtn:not(:disabled):hover {
    background: #2e6ba8;
    -webkit-box-shadow: 0 4px 9pt rgba(60,132,201,.4);
    box-shadow: 0 4px 9pt rgba(60,132,201,.4);
    -webkit-transform: translateX(-4px);
    transform: translateX(-4px)
}

#aiGenerateBtn:not(:disabled):active,#aiValidateBtn:not(:disabled):active {
    -webkit-transform: translateX(-4px) translateY(0);
    transform: translateX(-4px) translateY(0);
    background: #265494
}

#aiGenerateBtn:disabled,#aiValidateBtn:disabled {
    background: #747678;
    cursor: not-allowed;
    -webkit-box-shadow: none;
    box-shadow: none;
    -webkit-transform: none;
    transform: none
}

#aiGenerateBtn:focus,#aiValidateBtn:focus {
    outline: 2px solid #ffb81c;
    outline-offset: -2px
}

@media (prefers-reduced-motion:reduce) {
    #aiGenerateBtn,#aiValidateBtn {
        -webkit-transition: none;
        transition: none
    }

    #aiGenerateBtn:not(:disabled):hover,#aiValidateBtn:not(:disabled):hover {
        -webkit-transform: none;
        transform: none
    }
}

label {
    font-weight: 700
}

